begin;

update public.ai_prompts
set prompt_text = prompt_text || E'\n\nقواعد سياقية شاملة لاكتشاف التاريخ والوقت عبر قوالب الجهات المالية المختلفة:\n- لا تشترط وجود كلمة التاريخ أو الوقت بجانب القيمة. استدل من البنية الإنشائية الكاملة للمستند، وموقع النص، والترويسة، والتذييل، والختم، وسطر الإصدار، وجدول تفاصيل العملية.\n- افحص كامل الصورة من أعلى إلى أسفل ومن اليمين إلى اليسار، بما في ذلك الزوايا والتذييل السفلي؛ فقد يظهر الوقت وحده في أسفل الإشعار بينما يظهر التاريخ في أعلى المستند.\n- إذا ظهر تاريخ واحد ووقت واحد واضحان في المستند ولا توجد أزمنة منافسة، فادمجهما كتاريخ ووقت العملية حتى لو كانا في موضعين مختلفين أو بلا تسميات.\n- إذا ظهر الوقت في سطر تذييل رسمي تابع لنفس الإشعار، مثل 26/05/2026 04:08:56 PM، فهو وقت صريح للعملية أو إصدار الإشعار، ويجب استخراجه مع transaction_time_present=true ما لم توجد قرينة أقوى على أنه وقت طباعة غير متعلق بالعملية.\n- إذا ظهرت عدة أوقات، اختر الوقت الأقرب سياقيًا إلى تاريخ العملية أو قسم بيانات العملية، ولا تستخدم ساعة الهاتف أو شريط الحالة أو وقت لقطة الشاشة أو بيانات المتصفح.\n- ميّز بين محتوى المستند وبين عناصر واجهة الهاتف المحيطة بالصورة؛ لا تستخرج الوقت من شريط حالة الهاتف.\n- لا تجعل وجود كلمة التاريخ شرطًا لاكتشاف الوقت. الكلمات الدلالية مجرد قرائن إضافية وليست قاعدة حصرية.\n- استخدم السياق البصري: المحاذاة داخل نفس الإطار، الخط، الجدول، التذييل الرسمي، وأختام المؤسسة لتحديد ارتباط الوقت بالعملية.\n- عند وجود وقت بصيغة 12 ساعة، حوّله بدقة إلى 24 ساعة مع +03:00. مثال 04:08:56 PM = 16:08:56+03:00.\n- أعد transaction_time_present=true لكل وقت صريح تقرأه من المستند وترتبط به العملية سياقيًا، حتى لو لم يظهر حقل مستقل باسم الوقت.\n- جميع التواريخ والأوقات والأرقام في JSON يجب أن تستخدم الأرقام اللاتينية 0-9 فقط.\n- قبل الإخراج نفذ فحصًا نهائيًا: ابحث عن أي نمط وقت HH:MM أو HH:MM:SS مع AM/PM أو ص/م في كامل المستند، ثم قرر علاقته بالعملية سياقيًا.\n',
    version = greatest(version, 4),
    notes = 'Contextual multi-template date/time extraction; detects unlabeled footer times and enforces Latin digits.',
    updated_at = now()
where prompt_key = 'sanad_operation_extraction_v1'
  and version < 4;

commit;
